async (page) => {
  const errors = [], assert = (value, message) => { if (!value) throw new Error(message) }
  page.on('pageerror', error => errors.push(error.message))
  await page.route('**/api/visual-curator/resource**', route => route.fulfill({ contentType: 'image/svg+xml', body: '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="240"><rect width="400" height="240" fill="#526956"/></svg>' }))
  await page.goto(new URL('task-navigation.html', page.url()).href)
  await page.locator('[data-search-batch="task-a"]').waitFor()
  await page.getByRole('button', { name: '更多批次', exact: true }).click()
  await page.locator('[data-search-batch="task-b"]').waitFor()
  await page.evaluate(() => { window.taskNavigationFixture.flags.holdSession = true; window.taskNavigationFixture.flags.holdRuns = true })
  await page.locator('[data-search-batch="task-a"]').getByRole('button', { name: '任务详情', exact: false }).click()
  await page.locator('[data-task-target="task-a"]').waitFor()
  assert(await page.locator('[data-search-batch]').count() === 0, 'opening detail flashed a collection batch page')
  assert((await page.locator('.vc-main').innerText()).includes('任务详情'), 'the pending route did not identify task details')
  await page.evaluate(() => { window.taskNavigationFixture.flags.holdSession = false; window.taskNavigationFixture.release('session') })
  await page.waitForFunction(() => window.taskNavigationFixture.flags.calls.some(call => call.operation === 'run-get'))
  assert(!(await page.locator('.vc-main').innerText()).includes('Old unrelated'), 'another task flashed before the target response')
  await page.evaluate(() => { window.taskNavigationFixture.flags.holdRuns = false; window.taskNavigationFixture.release('run') })
  await page.locator('.vc-task-detail .vc-result-card').waitFor()
  const selected = page.locator('.vc-task-filters button').filter({ hasText: '预览匹配' }), review = page.locator('.vc-task-filters button').filter({ hasText: '待复核' }), rejected = page.locator('.vc-task-filters button').filter({ hasText: '不符合风格' })
  await page.evaluate(() => { window.taskNavigationFixture.flags.holdRuns = true })
  await review.click()
  assert(await review.getAttribute('aria-pressed') === 'true', 'category selection waited for the response')
  assert(await rejected.isEnabled(), 'another category was blocked by a pending read')
  assert(await page.locator('.vc-task-detail .vc-result-card img').count() === 0, 'old category images remained visible')
  await rejected.click()
  await page.evaluate(() => window.taskNavigationFixture.release('run', 'review'))
  assert(await rejected.getAttribute('aria-pressed') === 'true', 'an old category response changed the selected category')
  await page.evaluate(() => window.taskNavigationFixture.release('run', 'rejected'))
  await page.locator('.vc-task-detail img[alt="rejected-image"]').waitFor()
  await selected.click()
  await page.locator('.vc-task-detail img[alt="selected-image"]').waitFor()
  assert(await selected.getAttribute('aria-pressed') === 'true', 'cached category did not restore before its held revalidation')
  await page.evaluate(() => { window.taskNavigationFixture.flags.holdRuns = false; window.taskNavigationFixture.release('run'); window.taskNavigationFixture.flags.holdOwner = true; window.taskNavigationFixture.flags.holdBatches = true })
  await page.getByRole('button', { name: '返回素材库', exact: true }).click()
  await page.locator('[data-search-batch="task-b"]').waitFor()
  assert(await page.locator('[data-search-batch]').count() === 2, 'return lost a previously loaded batch page')
  assert(await page.locator('.vc-search-batch-skeleton').count() === 0, 'valid saved batch pages were replaced by a skeleton')
  await page.evaluate(() => { window.taskNavigationFixture.flags.holdBatches = false; window.taskNavigationFixture.release('batches'); window.taskNavigationFixture.flags.holdOwner = false; window.taskNavigationFixture.release('owner'); window.taskNavigationFixture.batches.select('task-b') })
  await page.waitForFunction(() => window.taskNavigationFixture.status().batchId === 'task-b' && window.taskNavigationFixture.status().batches?.[0] === 'task-b')
  await page.getByRole('button', { name: 'Native open task A', exact: true }).click()
  await page.locator('.vc-task-detail img[alt="selected-image"]').waitFor()
  await page.evaluate(() => { window.taskNavigationFixture.flags.holdOwner = true; window.taskNavigationFixture.flags.holdBatches = true })
  await page.getByRole('button', { name: '返回素材库', exact: true }).click()
  await page.locator('[data-search-batch="task-b"]').waitFor()
  assert(await page.evaluate(() => window.taskNavigationFixture.status().batchId) === 'task-b', 'native task navigation overwrote the collection filter')
  assert(await page.locator('[data-search-batch="task-a"]').count() === 0, 'return reset the selected batch filter')
  await page.setViewportSize({ width: 390, height: 844 })
  assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), 'narrow navigation overflowed')
  await page.evaluate(() => window.taskNavigationFixture.dispose())
  assert(errors.length === 0, errors.join('\n'))
  return { immediateTaskRoute: true, noWrongTaskFlash: true, responsiveCategories: true, cachedCategory: true, restoredPages: 2, restoredFilter: 'task-b', narrowFits: true, errors }
}
